50	  }
51	  const problems = [];
52	  const bad = (what, fix) => problems.push({ what, fix });
53	
54	  if (typeof decl.id !== 'string' || decl.id.trim() === '') {
55	    bad('the task has no string "id"', 'give the task an "id" matching its directory name');
56	  }
57	  if (!FREQUENCIES.includes(decl.frequency)) {
58	    bad(`"frequency" ${JSON.stringify(decl.frequency)} is not a legal frequency`, `set one of: ${FREQUENCIES.join(', ')}`);
59	  }
60	  if (!Array.isArray(decl.precondition_signals) || !decl.precondition_signals.every((s) => SIGNAL_NAMES.includes(s))) {
61	    bad(`"precondition_signals" must be an array of known signal names`, `use only: ${SIGNAL_NAMES.join(', ')}`);
62	  }
63	  if (!MODEL_FAMILIES.includes(decl.agent_model)) {
64	    bad(`"agent_model" ${JSON.stringify(decl.agent_model)} is not a legal model family`, `set one of: ${MODEL_FAMILIES.join(', ')}`);
65	  }
