84	  // scheduler runs as a subprocess before the agent. When present it must be a
85	  // non-empty, task-local command AND carry a positive-integer
86	  // agent_preprocessing_timeout — the hard kill that bounds the subprocess.
87	  if (decl.agent_preprocessing !== undefined) {
88	    if (typeof decl.agent_preprocessing !== 'string' || decl.agent_preprocessing.trim() === '') {
