31	//             dispatch to the `ready-for-agent-fleet` label so a distinct executor
32	//             routine (with the owner's repos in its sources) runs it.
33	export const SESSION_SCOPES = ['self', 'fleet'];
34	
35	// The signal-collector vocabulary (DESIGN §3.3). A task collects only the union
36	// of what its due tasks declare. `fleet` is canon-only (consumers cannot declare
37	// it) — that restriction is enforced where signals are collected, not here; the
38	// shape check only asserts a declared name is a real collector.
39	export const SIGNAL_NAMES = [
40	  'commits', 'prs', 'issues', 'branches', 'release',
41	  'localPacks', 'sharedMount', 'conversationLogs', 'stamp', 'fleet',
42	];
