1	import { finding } from '../../engine/checks/helpers/findings.mjs';
2	import { FREQUENCIES } from '../../engine/scheduler/slots.mjs';
3	import { MODEL_FAMILIES } from '../../engine/scheduler/model-map.mjs';
4	import { OUTCOMES, SIGNAL_NAMES } from '../../engine/scheduler/task-contract.mjs';
5	
6	// Every scheduler task is a `tasks/<name>/task.mjs` whose default export carries
7	// the full declaration contract (per-project-scheduling DESIGN §1) with legal
8	// enum values. This asserts that shape statically at author time — the executor
9	// and scheduler validate the same contract at run time (task-contract.mjs), so
10	// an illegal frequency/model/outcome, or a missing field, is caught here first.
11	//
12	// RELEVANCE FIRST (engine/checks/README.md): gated on a `tasks/<name>/task.mjs`
13	// existing, so the check is inert on any repo without tasks. Static text over
14	// the self-contained module (task.mjs imports nothing), keyed off the canonical
15	// enum lists so the legal values never drift from the runtime validator.
16	const TASK_MJS = /(^|\/)tasks\/[^/]+\/task\.mjs$/;
17	
18	// The value of a top-level `key: 'value'` string field, or null if absent.
19	const strField = (text, key) => {
20	  const m = new RegExp(`\\b${key}:\\s*['"]([^'"]+)['"]`).exec(text);
21	  return m ? m[1] : null;
22	};
23	
24	const rule = {
25	  id: 'task-declaration-shape',
26	  severity: 'blocking',
27	  description: 'A tasks/<name>/task.mjs default-exports the full task contract (id, frequency, precondition_signals, agent_model, expected_outcome, agent_instructions, precondition) with legal enum values; an agentic task bounds its run with agent_execution_timeout, and any agent_preprocessing carries a timeout and stays task-local',
28	  doc: 'packs/basics/scheduled-tasks.md',
29	  why: 'the scheduler and executor read agent_model/expected_outcome/frequency from this file, not the dispatch issue — an illegal or missing value means a task never fires, fires wrong, or writes past its ceiling',
30	
31	  run(ctx) {
32	    const out = [];
33	    for (const file of ctx.files.filter((f) => TASK_MJS.test(f))) {
34	      const text = ctx.read(file);
35	      if (text === null) continue;
36	      const flag = (what, fix) => out.push(finding(rule, { file, what, fix }));
37	      const model = strField(text, 'agent_model');
38	
39	      if (!/export\s+default\s*\{/.test(text)) {
40	        flag('does not default-export a declaration object', 'export default { id, frequency, precondition_signals, agent_model, expected_outcome, agent_instructions, precondition }');
41	        continue;
42	      }
43	      const enumField = (key, legal) => {
44	        const v = strField(text, key);
45	        if (v === null) flag(`declares no "${key}"`, `add "${key}": one of ${legal.join(', ')}`);
46	        else if (!legal.includes(v)) flag(`"${key}" is "${v}", not a legal value`, `use one of: ${legal.join(', ')}`);
47	      };
48	      enumField('frequency', FREQUENCIES);
49	      enumField('agent_model', MODEL_FAMILIES);
50	      enumField('expected_outcome', OUTCOMES);
51	
52	      if (!/\bid:\s*['"]/.test(text)) flag('declares no string "id"', 'add "id": the task name (matching its directory)');
53	      if (!/\bagent_instructions:\s*['"]/.test(text)) flag('declares no string "agent_instructions"', 'add "agent_instructions": the worker file beside task.mjs (e.g. "task.md")');
54	      if (!/\bprecondition_signals:\s*\[/.test(text)) {
55	        flag('declares no "precondition_signals" array', `add "precondition_signals": an array of ${SIGNAL_NAMES.join(', ')}`);
56	      }
57	      if (!/\bprecondition\s*[:(]/.test(text)) {
58	        flag('declares no "precondition" function', 'add a precondition(signals, config) that returns { run, reason, context? }');
59	      }
60	
61	      // The preprocessing/timeout guards (agent-preprocessing DESIGN §2). Numeric
62	      // presence is a cheap `<key>: <digit>` regex, matching the runtime contract.
63	      const hasNum = (key) => new RegExp(`\\b${key}:\\s*\\d`).test(text);
64	      const hasPreprocessing = /\bagent_preprocessing:\s*['"]/.test(text);
65	      if (model && MODEL_FAMILIES.includes(model) && model !== 'none' && !hasNum('agent_execution_timeout')) {
66	        flag('an agentic task (agent_model !== "none") declares no numeric "agent_execution_timeout"', 'add "agent_execution_timeout": seconds bounding the agentic run');
67	      }
68	      if (model === 'none' && !hasPreprocessing) {
69	        flag('an agentless task (agent_model: "none") declares no "agent_preprocessing"', 'add "agent_preprocessing" (a none task does its work in that subprocess) — or give the task an agent_model');
70	      }
71	      if (hasPreprocessing) {
72	        const prep = strField(text, 'agent_preprocessing');
73	        if (prep && (/(^|\s)\//.test(prep) || prep.includes('..'))) {
74	          flag('"agent_preprocessing" reaches outside the task directory (absolute path or "..")', 'reference a sibling script only, e.g. "node prepare.mjs"');
75	        }
76	        if (!hasNum('agent_preprocessing_timeout')) {
77	          flag('"agent_preprocessing" is set but declares no numeric "agent_preprocessing_timeout"', 'add "agent_preprocessing_timeout": seconds after which the subprocess is killed');
78	        }
79	      }
80	    }
81	    return out;
82	  },
83	};
84	
85	export default rule;
86

