8	// --- model-map ---
9	test('resolveModel maps every family and rejects unknowns; none is agentless', () => {
10	  for (const f of MODEL_FAMILIES) assert.equal(resolveModel(f), MODEL_MAP[f]);
11	  assert.equal(resolveModel('none'), null);
12	  assert.equal(isAgentless('none'), true);
13	  assert.equal(isAgentless('opus'), false);
14	  assert.throws(() => resolveModel('gpt'), /unknown model family/);
15	});
