33	test('validateTaskDeclaration: session_scope is optional, defaults valid, and rejects a bad value', () => {
34	  assert.deepEqual(validateTaskDeclaration(validTask), []);                                  // omitted → fine (defaults to self)
35	  assert.deepEqual(validateTaskDeclaration({ ...validTask, session_scope: 'self' }), []);
36	  assert.deepEqual(validateTaskDeclaration({ ...validTask, session_scope: 'fleet' }), []);
37	  assert.match(validateTaskDeclaration({ ...validTask, session_scope: 'global' })[0].what, /not a legal session scope/);
38	});
