40	test('validateTaskDeclaration requires agent_execution_timeout on an agentic task', () => {
41	  const { agent_execution_timeout, ...noBound } = validTask;
42	  assert.match(validateTaskDeclaration(noBound)[0].what, /no positive-integer "agent_execution_timeout"/);
43	  // a non-integer or non-positive bound is equally rejected
44	  assert.ok(validateTaskDeclaration({ ...validTask, agent_execution_timeout: 0 }).length);
45	  assert.ok(validateTaskDeclaration({ ...validTask, agent_execution_timeout: 12.5 }).length);
46	});
