48	test('validateTaskDeclaration: an agentless (none) task needs preprocessing but no execution bound', () => {
49	  const none = { ...validTask, agent_model: 'none', expected_outcome: 'none' };
50	  delete none.agent_execution_timeout;
51	  // a bare none task with no preprocessing does nothing → flagged
52	  assert.match(validateTaskDeclaration(none)[0].what, /declares no "agent_preprocessing"/);
53	  // with preprocessing + its timeout it is clean, and needs no execution bound
54	  assert.deepEqual(
55	    validateTaskDeclaration({ ...none, agent_preprocessing: 'node worker.mjs', agent_preprocessing_timeout: 120 }),
56	    [],
57	  );
